import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img } from '../remotionShim';
// Font loader isn't strictly necessary for an image component but good practice to keep the pattern
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type Floating3DImageProps = Record<string, any>;

const Floating3DImage: React.FC<Floating3DImageProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 10,
  imageUrl = "https://images.unsplash.com/photo-1472214103451-9374bd1c798e?q=80&w=2070&auto=format&fit=crop",
  glowColor = "#4f46e5",
  glowBlurRadius = 30,
  floatSpeed = 2,
  floatAmplitude = 20,
  tiltIntensity = 5,
  scale = 0.85,
  borderRadius = 24,
}) => {
  // Although we aren't using text, we maintain the pattern
  useFontLoader([]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Calculate floating motion
  // We use a sine wave for smooth periodic motion
  // frame / fps gives time in seconds
  const time = frame / fps;
  
  // Bobbing up and down (Y axis translation)
  const translateY = Math.sin(time * floatSpeed) * floatAmplitude;

  // Tilting (Rotation)
  // We offset the phase by Math.PI / 2 so the rotation aligns nicely with the movement
  // e.g., as it moves up, it might tilt back slightly
  const rotateX = Math.cos(time * floatSpeed) * tiltIntensity;
  const rotateY = Math.sin(time * floatSpeed * 0.5) * (tiltIntensity * 0.5); // Slower Y rotation for variance

  // Dynamic shadow that pulses slightly with the movement
  // When the object is "closer" (visualized by bobbing), the shadow might change intensity
  const shadowOpacity = 0.6 + Math.sin(time * floatSpeed) * 0.2; 
  
  // Convert hex color to rgba for shadow opacity handling if needed, 
  // but here we can just use the color directly or assume hex.
  // Ideally, we'd parse the color, but for simplicity/stability in this context, 
  // we'll rely on the solid color + a potential wrapper if we needed opacity.
  // For now, standard box-shadow with the user's color is robust.
  
  const containerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    perspective: "1500px", // Critical for 3D effect
    width: "100%",
    height: "100%",
    backgroundColor: finalBgColor,
  };

  const cardStyle: React.CSSProperties = {
    position: "relative",
    width: width * 0.8, // Takes up most of the screen width
    // Maintain a 16:9 aspect ratio roughly, or responsive based on image
    // Here we set a max-height to ensure it doesn't overflow vertically on standard screens
    height: height * 0.7, 
    transformStyle: "preserve-3d",
    transform: `translateY(${translateY}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(${scale})`,
    borderRadius: borderRadius,
    boxShadow: `0px 0px ${glowBlurRadius}px ${glowColor}`,
    overflow: "hidden", // Ensures image respects border radius
    // Add a border to emphasize the glow
    border: `2px solid ${glowColor}40`, // Low opacity border matching glow
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={cardStyle}>
        <Img
          src={imageUrl}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover", // Ensures the image fills the card area
          }}
        />
        
        {/* Optional: Add a subtle sheen/reflection overlay for more 3D realism */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 50%, rgba(0,0,0,0.1) 100%)",
            pointerEvents: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default Floating3DImage;